from flask import Flask, request, jsonify, Response
import sqlite3, os, base64

app = Flask(__name__)
DB = os.path.join(os.path.dirname(os.path.abspath(__file__)), "codex.db")

_HTML_B64 = ""
HTML = base64.b64decode(_HTML_B64).decode("utf-8")

SOURCES = ("Python", "R", "SQL", "Excel", "Project")

def get_db():
    conn = sqlite3.connect(DB)
    conn.row_factory = sqlite3.Row
    return conn

def init_db():
    with get_db() as conn:
        conn.execute("""
            CREATE TABLE IF NOT EXISTS snippets_new (
                id          INTEGER PRIMARY KEY AUTOINCREMENT,
                source      TEXT    NOT NULL,
                name        TEXT    NOT NULL,
                description TEXT    DEFAULT '',
                code        TEXT    NOT NULL,
                importance  INTEGER NOT NULL DEFAULT 3,
                copy_count  INTEGER NOT NULL DEFAULT 0,
                created_at  DATETIME DEFAULT CURRENT_TIMESTAMP,
                updated_at  DATETIME DEFAULT CURRENT_TIMESTAMP
            )
        """)
        old = conn.execute(
            "SELECT name FROM sqlite_master WHERE type='table' AND name='snippets'"
        ).fetchone()
        if old:
            cols = [r[1] for r in conn.execute("PRAGMA table_info(snippets)").fetchall()]
            cc = "copy_count" if "copy_count" in cols else "0"
            conn.execute(
                "INSERT OR IGNORE INTO snippets_new"
                " (id,source,name,description,code,importance,copy_count,created_at,updated_at)"
                " SELECT id,source,name,description,code,importance," + cc + ","
                " created_at,updated_at FROM snippets"
            )
            conn.execute("DROP TABLE snippets")
        conn.execute("ALTER TABLE snippets_new RENAME TO snippets")
        conn.commit()

@app.route("/")
def index():
    return Response(HTML, mimetype="text/html")

@app.route("/api/snippets", methods=["GET"])
def list_snippets():
    with get_db() as conn:
        rows = conn.execute(
            "SELECT * FROM snippets ORDER BY importance DESC, updated_at DESC"
        ).fetchall()
    return jsonify([dict(r) for r in rows])

@app.route("/api/snippets", methods=["POST"])
def create_snippet():
    d = request.json
    if not all(d.get(k) for k in ("source","name","code","importance")):
        return jsonify({"error": "Missing required fields"}), 400
    if d["source"] not in SOURCES:
        return jsonify({"error": "Invalid source"}), 400
    try:
        imp = int(d["importance"])
        assert 1 <= imp <= 5
    except Exception:
        return jsonify({"error": "Importance must be 1-5"}), 400
    with get_db() as conn:
        cur = conn.execute(
            "INSERT INTO snippets (source,name,description,code,importance) VALUES (?,?,?,?,?)",
            (d["source"], d["name"].strip(), d.get("description","").strip(), d["code"], imp)
        )
        conn.commit()
        row = conn.execute("SELECT * FROM snippets WHERE id=?", (cur.lastrowid,)).fetchone()
    return jsonify(dict(row)), 201

@app.route("/api/snippets/<int:sid>", methods=["PUT"])
def update_snippet(sid):
    d = request.json
    with get_db() as conn:
        row = conn.execute("SELECT * FROM snippets WHERE id=?", (sid,)).fetchone()
        if not row:
            return jsonify({"error": "Not found"}), 404
        fields = {
            "source":      d.get("source",      row["source"]),
            "name":        d.get("name",         row["name"]),
            "description": d.get("description",  row["description"]),
            "code":        d.get("code",          row["code"]),
            "importance":  int(d.get("importance", row["importance"])),
        }
        if fields["source"] not in SOURCES:
            return jsonify({"error": "Invalid source"}), 400
        if not 1 <= fields["importance"] <= 5:
            return jsonify({"error": "Importance must be 1-5"}), 400
        conn.execute("""
            UPDATE snippets
            SET source=?, name=?, description=?, code=?, importance=?,
                updated_at=CURRENT_TIMESTAMP
            WHERE id=?
        """, (*fields.values(), sid))
        conn.commit()
        updated = conn.execute("SELECT * FROM snippets WHERE id=?", (sid,)).fetchone()
    return jsonify(dict(updated))

@app.route("/api/snippets/<int:sid>/copy", methods=["POST"])
def increment_copy(sid):
    with get_db() as conn:
        if not conn.execute("SELECT 1 FROM snippets WHERE id=?", (sid,)).fetchone():
            return jsonify({"error": "Not found"}), 404
        conn.execute("UPDATE snippets SET copy_count = copy_count + 1 WHERE id=?", (sid,))
        conn.commit()
        updated = conn.execute("SELECT copy_count FROM snippets WHERE id=?", (sid,)).fetchone()
    return jsonify({"copy_count": updated["copy_count"]})

@app.route("/api/snippets/<int:sid>", methods=["DELETE"])
def delete_snippet(sid):
    with get_db() as conn:
        if not conn.execute("SELECT 1 FROM snippets WHERE id=?", (sid,)).fetchone():
            return jsonify({"error": "Not found"}), 404
        conn.execute("DELETE FROM snippets WHERE id=?", (sid,))
        conn.commit()
    return jsonify({"deleted": sid})

@app.route("/api/search", methods=["GET"])
def search_snippets():
    q = request.args.get("q", "").strip().lower()
    if not q:
        return jsonify([])
    with get_db() as conn:
        rows = [dict(r) for r in conn.execute("SELECT * FROM snippets").fetchall()]
    results = []
    for r in rows:
        score = 0
        for word in q.split():
            if word in r["name"].lower():                  score += 10
            if word in r["source"].lower():                score += 6
            if word in (r["description"] or "").lower():   score += 4
            if word in r["code"].lower():                  score += 2
        if q in r["name"].lower(): score += 5
        if score > 0:
            r["_score"] = score
            results.append(r)
    results.sort(key=lambda x: (-x["_score"], -x["importance"]))
    return jsonify(results)

if __name__ == "__main__":
    init_db()
    port = 8080
    print(f"\n  CODEX running ->  http://localhost:{port}\n")
    app.run(debug=True, port=port, use_reloader=False)